import { Injectable } from '@angular/core';
import { SupportAPI } from '@imunify360-api/support';
import { XHR } from 'app/utils/xhr/xhr';
import { map, Observable } from 'rxjs';


@Injectable()
export class SupportService {
    constructor(public xhr: XHR) {}
    send = this.xhr.rx(SupportAPI.send);
    doctor = this.xhr.rx(SupportAPI.doctor);

    getDoctorKey(): Observable<string> {
        return this.doctor().pipe(
            map(response => {
                const message = response.data?.items;

                // Extract key from response
                const match = message?.match(/Please, provide this key:\s*\n(.+?)\s*\nto Imunify360 Support Team/);
                return match ? match[1] : '';
            })
        );
    }
}
