import {
    Component,
    ElementRef,
    HostListener,
    OnDestroy,
    ViewChild,
    AfterViewInit,
    Output,
    EventEmitter,
    Inject,
} from '@angular/core';
import { SupportService } from 'app/services/support';
import { take } from 'rxjs';
import { Panel } from 'app/utils/panel';

@Component({
    selector: 'ai-support-iframe',
    styleUrls: ['ai-support-iframe.component.scss'],
    templateUrl: 'ai-support-iframe.component.html',
})
export class AiSupportIframeComponent implements OnDestroy, AfterViewInit {
    @Output() iframeLoaded = new EventEmitter<void>();
    @ViewChild('chatbotIframe', { static: true }) chatbotIframe: ElementRef<HTMLIFrameElement>;

    private ro?: ResizeObserver;
    private doctorRequestRunning = false;
    private docktorKey: string;

    public constructor(
        private iframeContainer: ElementRef,
        private supportService: SupportService,
        private panel: Panel,
        @Inject('Window') private window: Window,
    ) {
        this.window.addEventListener('message', (event) => {
            const allowedOrigins = [
                'https://chatbot.cloudlinux.com'
            ];

            if (!allowedOrigins.some(url => event.origin.startsWith(url))) {
                return;
            }
            // this.onIframeReady(); // not reliable

            // Handle custom fields request from chatbot
            if (event.data.type === 'clbot.customFields.request') {
                this.handleCustomFieldsRequest(event.data.data);
            }
        });
    }

    ngAfterViewInit(): void {
        this.resizeIframeToAvailableSpace();
        // Observe layout shifts that change element's top position
        if ('ResizeObserver' in window) {
            this.ro = new ResizeObserver(() => this.resizeIframeToAvailableSpace());
            this.ro.observe(document.documentElement);
            this.ro.observe(document.body);
        }
        // Also adjust once the iframe loads (fonts/layout can shift)
        this.chatbotIframe?.nativeElement?.addEventListener('load', () => {
            this.resizeIframeToAvailableSpace();
            this.onIframeReady();
        });
    }

    @HostListener('window:resize')
    onWindowResize() {
        this.resizeIframeToAvailableSpace();
    }

    private onIframeReady(): void {
        // send notification about iframe ready with a delay to avoid a change detection error
        setTimeout(() => {
            this.iframeLoaded.emit();
        }, 100);
    }

    private resizeIframeToAvailableSpace() {
        const container = this.iframeContainer?.nativeElement;
        if (!container) return;
        // Distance from container top to viewport top
        const rect = container.getBoundingClientRect();
        const viewportH = window.innerHeight || document.documentElement.clientHeight;
        const panelMargin = this.getAdditionalPanelRelatedMargin();

        // Remaining space from container top to bottom of viewport
        const available = Math.max(0, viewportH - rect.top - panelMargin);
        container.style.height = `${Math.max(560, available)}px`;
    }

    private getAdditionalPanelRelatedMargin(): number {
        // each panel has its own margin;
        // to avoid additional scroll, we need to use its value for calculation iframe height
        if (this.panel.isCpanel) return 47;
        if (this.panel.isPlesk) return 61;
        if (this.panel.isNoPanel) return 10;
        if (this.panel.isDirectAdmin) return 50;

        return 40;
    }

    private handleCustomFieldsRequest(requestData) {
        const { runDoctor } = requestData;

        // Execute Imunify360 doctor tool if requested (this takes 30-60 seconds)
        if (runDoctor) {
            if (this.docktorKey) {
                this.postMessageToIframe(runDoctor, this.docktorKey);
            }
            if (this.doctorRequestRunning) {
                return;
            }
            this.doctorRequestRunning = true;
            this.supportService.getDoctorKey()
                .pipe(take(1))
                .subscribe({
                    next: key => {
                        this.docktorKey = key;
                        this.doctorRequestRunning = false;
                        this.postMessageToIframe(runDoctor, key);
                    },
                    error: () => {
                        this.doctorRequestRunning = false;
                    }
                });
            return;
        }

        this.postMessageToIframe(runDoctor);
    }

    private postMessageToIframe(runDoctor: boolean, doctorKey: string = ''): void {
        const productId = 'pr_im360';

        this.chatbotIframe?.nativeElement?.contentWindow?.postMessage({
            type: 'clbot.customFields',
            data: {
                fields: [
                    { id: 43297669, value: doctorKey },
                    { id: 5961407579676, value: productId }
                ],
                timestamp: new Date().toISOString(),
                doctorExecuted: runDoctor && !!doctorKey
            }
        }, '*');
    }

    ngOnDestroy(): void {
        this.ro?.disconnect();
    }
}
